    ("react-ui-model", "What React Is and Why It Is Used", "foundations", "basic", "React is a JavaScript library for describing user interfaces as components. It updates the rendered UI when the data used by a component changes.", "Component tree: App → Header + ProductList → ProductCard", "What problem does React solve?", "It helps teams split interfaces into reusable pieces and keep the rendered UI in sync with changing data."),
    ("react-component", "Function Components", "foundations", "basic", "A function component accepts props and returns a description of UI. Components make a screen easier to reuse, test and reason about.", "function Greeting({ name }) { return <h1>Hello, {name}</h1>; }", "What does a function component return?", "It returns React elements, commonly written with JSX, that describe what should be rendered."),
    ("react-jsx", "JSX and JavaScript Expressions", "foundations", "basic", "JSX is syntax that lets JavaScript describe element trees. Expressions are placed inside braces; attributes and escaping follow JSX rules.", "<p className=\"notice\">Hello, {user.name}</p>", "How do you include a JavaScript expression in JSX?", "Place it inside curly braces, such as {user.name}."),
    ("react-props", "Props and Component Contracts", "foundations", "basic", "Props pass inputs from a parent to a child. Treat them as read-only and make required versus optional values clear.", "<Button tone=\"primary\" disabled={saving}>Save</Button>", "Should a child component mutate its props?", "No. Props are inputs owned by the parent; the child should derive its output from them."),
    ("react-conditional", "Conditional Rendering", "foundations", "basic", "Render different elements for loading, success, empty and error states using normal JavaScript conditions.", "if (loading) return <Spinner />; if (error) return <Error />;", "Why render explicit loading and error states?", "They make the interface reflect the real request state and give users useful feedback."),
    ("react-lists-keys", "Lists and Stable Keys", "foundations", "basic", "Keys identify siblings across renders so React can match items when a list changes. Prefer stable IDs over array indexes for mutable lists.", "items.map(item => <Row key={item.id} item={item} />)", "Why can an array index be a poor key?", "If items reorder or are removed, an index can point to a different item and preserve the wrong component state."),
    ("react-events", "Events and Event Handlers", "state", "basic", "Pass event handler functions to JSX props. The handler should express the user action and update state through the intended state API.", "<button onClick={() => setOpen(true)}>Open</button>", "What is the difference between onClick={save} and onClick={save()}?", "The first passes the handler; the second calls it during render and passes its return value."),
    ("react-usestate", "State with useState", "state", "basic", "State stores values that affect rendered UI. Calling its setter schedules a render with the new value; do not mutate an existing object or array in place.", "const [count, setCount] = useState(0);", "How should state be changed?", "Call the setter with a replacement value; use a functional update when the next value depends on the previous one."),
    ("react-state-structure", "Choose Good State Structure", "state", "intermediate", "Keep one source of truth and avoid storing values that can be derived from other state. This reduces synchronization bugs.", "const total = items.reduce((sum, item) => sum + item.price, 0);", "Why avoid duplicated derived state?", "Two copies can diverge and require extra effects or event handlers to keep them synchronized."),
    ("react-forms", "Controlled Forms and Validation", "data", "basic", "A controlled field reads its value from state and updates that state on change. Validate input at the appropriate boundaries and show field-specific feedback.", "<input value={email} onChange={e => setEmail(e.target.value)} />", "What makes an input controlled?", "Its current value comes from React state, and an event handler updates that state."),
    ("react-useeffect", "Effects and External Systems", "state", "intermediate", "Effects synchronize a component with external systems such as subscriptions, browser APIs or network connections. They are not a general replacement for derived values or event handlers.", "useEffect(() => { const id = setInterval(tick, 1000); return () => clearInterval(id); }, []);", "When should an effect be used?", "When rendering must synchronize with an external system, with cleanup for subscriptions or resources."),
    ("react-effect-deps", "Effect Dependencies and Cleanup", "state", "intermediate", "An effect dependency list describes the reactive values it reads. Cleanup runs before the effect repeats and when the component unmounts.", "useEffect(() => subscribe(roomId), [roomId]);", "What happens when a dependency changes?", "React runs the previous cleanup, then runs the effect again with the new values."),
    ("react-refs", "Refs and DOM Access", "state", "intermediate", "Refs hold values that do not drive rendering, such as a DOM node or timer ID. Updating a ref does not cause a re-render.", "const inputRef = useRef(null); inputRef.current?.focus();", "When is a ref appropriate?", "For imperative access or mutable values that should persist without triggering a render."),
    ("react-context", "Context and Shared State", "data", "intermediate", "Context passes a value through a component subtree without manually forwarding props at every level. Keep providers scoped and avoid putting rapidly changing unrelated values in one context.", "<ThemeContext value={theme}><App /></ThemeContext>", "When is context useful?", "When many descendants need the same value, such as a theme, locale or authenticated user."),
    ("react-data-fetch", "Data Fetching and Request States", "data", "intermediate", "A data flow should represent loading, success, empty and error outcomes. Cancel or ignore obsolete requests when the selected resource changes.", "loading → fetch project → success | error", "What should an async screen represent besides success?", "Loading, empty and error states, plus cancellation or stale-response handling where needed."),
    ("react-router", "Client-Side Routing", "data", "intermediate", "A router maps URLs to screen components and manages navigation history. Route boundaries should handle missing pages and preserve useful link semantics.", "Route /projects/:projectId → ProjectPage", "Why use real links for navigation?", "Links preserve keyboard access, open-in-new-tab behavior and browser navigation conventions."),
    ("react-custom-hooks", "Custom Hooks", "state", "intermediate", "A custom hook packages reusable stateful logic while following the Rules of Hooks. It shares behavior, not a shared state instance by default.", "function useOnline() { /* subscribe to online/offline */ }", "What does a custom hook reuse?", "Stateful logic and effects; each caller still gets its own hook state unless the hook connects to shared state."),
    ("react-memo", "Memoization and Rendering Performance", "quality", "advanced", "Memoization can skip work when inputs are stable, but it adds complexity and does not fix expensive architecture or incorrect state boundaries.", "Profile first; memoize a measured expensive calculation", "When should a component be memoized?", "When profiling shows avoidable rerenders are a meaningful cost and its inputs can be compared reliably."),
    ("react-testing", "Component and Interaction Testing", "quality", "intermediate", "Test observable behavior: what users see and do. Keep tests focused on accessible labels, state changes, loading, errors and important flows.", "getByRole('button', { name: 'Save' })", "What should a user-focused component test assert?", "The visible behavior and accessible interactions, rather than private implementation details."),
    ("react-accessibility", "Accessible React Interfaces", "quality", "intermediate", "Use semantic elements, labels, keyboard interaction and status announcements. Accessibility is part of component behavior, not a final styling pass.", "<label htmlFor=\"email\">Email</label><input id=\"email\" />", "Why prefer a native button to a clickable div?", "A button already supports keyboard activation, focus and the correct accessibility role."),
